function m = yoloErrorModel()
%YOLOERRORMODEL Calibrated YOLO box-error model (generated by tools/yolo/gen_model.py).
%   Fitted on recordings/real01 (dets_all.csv vs projected GT, tools/yolo/fit_tables.py,
%   fit_k.py).  Tables are indexed by the MEASURED box size and interpolated
%   (clamped at the ends).  The ball box is biased ~+1.7 px (true width = 0.8..0.9*w);
%   at long range (w<8 px) the detector box saturates, so the size cue is weak.
%   m.kR / m.kRes: heavy-tail inflation of the first-order range std so that
%   ~99%% of errors lie inside 3 sigma, indexed by the estimated range.
m.ball.s     = [6.09 7.1 8.035 9.21 11.06 13.22 15.29 17.75 22.76 30.86];   % measured box size (ball: width, robot: height) [px], knots
m.ball.sTrue = [4.947 5.61 6.728 7.7 9.185 12.12 14.3 16.05 19.64 27.97];   % median true size at that measured size [px]
m.ball.sSd   = [0.5419 0.5605 0.632 0.6928 0.7158 0.672 0.6431 1.008 1.4 1.718];   % robust std of true size [px]
m.ball.vBias = [0.3207 0.1192 0.0008442 0.08148 -0.007051 -0.04594 -0.2554 -0.224 -0.1279 -0.8738];   % robust bias of the range row (ball centre / robot foot) [px]
m.ball.vSd   = [0.4112 0.4217 0.4285 0.5052 0.5665 0.5631 0.496 0.4541 0.9974 1.255];   % robust std of that row [px]
m.ball.uSd   = [0.2423 0.2525 0.2773 0.3746 0.4598 0.4567 0.4288 0.626 0.8881 1.102];   % robust std of the box centre column [px]
m.robot.s     = [24.56 27.95 32.91 39.16 49.97 61.59 76.65 102.7 127.3];   % measured box size (ball: width, robot: height) [px], knots
m.robot.sTrue = [23.84 26.84 32.25 38.52 51.5 64.06 77.98 103.9 125.1];   % median true size at that measured size [px]
m.robot.sSd   = [1.706 1.599 1.674 2.209 2.807 3.409 3.563 5.1 5.797];   % robust std of true size [px]
m.robot.vBias = [1.25 1.207 1.131 0.8962 0.7087 0.4628 0.2852 0.3936 0.1734];   % robust bias of the range row (ball centre / robot foot) [px]
m.robot.vSd   = [0.6821 0.6593 0.8509 0.9394 1.196 1.342 1.746 2.731 3.262];   % robust std of that row [px]
m.robot.uSd   = [1.166 1.205 1.276 1.583 1.798 2.177 2.586 3.627 4.147];   % robust std of the box centre column [px]
m.ball.kR    = [1.748 3.232 5.114 6.647 8.78];   % estimated range knots [m]
m.ball.kVal  = [1 1.048 1.397 1.397 1.397];   % range-std inflation at those ranges
m.ball.cEdge = [0 0.8 1.01];   % conf group edges
m.ball.cFac  = [3.827 1];   % extra std factor per conf group
m.robot.kR    = [1.827 3.024 4.986 6.628 8.492];   % estimated range knots [m]
m.robot.kVal  = [1.882 1.733 1.423 1.211 1.099];   % range-std inflation at those ranges
m.robot.cEdge = [0 0.5 0.7 1.01];   % conf group edges
m.robot.cFac  = [3.097 1.548 1.006];   % extra std factor per conf group
% validity rule (ball): low quality if the box is too small / not round / low conf
m.ball.minW = 8;  m.ball.maxAspect = 0.2;  m.ball.confSmall = 0.7;
m.robot.minH = 14;
m.ball.lqFac = 1.108;  m.robot.lqFac = 1;   % extra std factor for LowQuality detections
m.ball.kB = 1.147;  m.robot.kB = 1.277;   % bearing std inflation
end
